/**
 * Code-tab Forth bench corpus: a representative set of blocks → Forth programs
 * is GENERATED by bw-lang/forth.js and then actually RUN on the real shipped
 * zForth (static/roms/forth.exe) on the DOS bench — the same production path
 * runDosToolchain('forth', …) takes. Where code-tab-forth.test.mjs checks the
 * two-way text contract (generate → read → generate), this checks that the
 * generated Forth *executes correctly* across the full supported surface:
 * arithmetic, if/else, REPEAT, nested REPEAT, REPEAT UNTIL, and custom blocks
 * (incl. proc-calls-proc). Each case also re-asserts the round-trip fixed point
 * cheaply, so one corpus guards both halves.
 */
import {test} from 'node:test';
import assert from 'node:assert/strict';
import path from 'node:path';
import {readFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';

const SOURCE = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', 'overlay', 'scratch-gui');
const SB3Creator = (await import(path.join(SOURCE, 'src/lib/sb3-creator.js'))).default;
const {generateForth, default: forthToPseudocode} =
    await import(path.join(SOURCE, 'src/lib/bw-lang/forth.js'));
const {runDosToolchain} = await import(path.join(SOURCE, 'src/lib/bw-debug/dos-toolchain-routes.js'));
const FORTH_EXE = new Uint8Array(readFileSync(path.join(SOURCE, 'static/roms/forth.exe')));

const project = src => { const c = new SB3Creator(); c.parse(src); return c.project; };

// Each case: pseudocode → generateForth → run on the real forth.exe. `expect`
// substrings must appear in the console; `absent` must not (so a loop provably
// stops). Numbers print with a trailing space (`.`), so expectations include it.
const CORPUS = {
    'arithmetic + if/else': {
        src: `GLOBAL a
WHEN flag clicked:
  set a to ((3 + 4) * 2)
  say a
  IF (a > 10) THEN:
    say "big"
  ELSE:
    say "small"
`,
        expect: ['14 ', 'big'],
        absent: ['small']
    },
    'REPEAT accumulates': {
        src: `GLOBAL sum
WHEN flag clicked:
  set sum to 0
  REPEAT 5:
    change sum by 1
  say sum
`,
        expect: ['5 '],
        absent: ['6 ']
    },
    'nested REPEAT': {
        src: `GLOBAL n
WHEN flag clicked:
  set n to 0
  REPEAT 2:
    REPEAT 3:
      change n by 1
  say n
`,
        expect: ['6 '],
        absent: ['7 ']
    },
    'REPEAT UNTIL counts down': {
        src: `GLOBAL n
WHEN flag clicked:
  set n to 10
  REPEAT UNTIL (n < 1):
    change n by -1
  say n
`,
        expect: ['0 '],
        absent: ['-1 ']
    },
    'custom blocks, proc-calls-proc, globals': {
        src: `GLOBAL total
DEFINE add_one:
  change total by 1
DEFINE add_three:
  add_one
  add_one
  add_one
WHEN flag clicked:
  set total to 0
  add_three
  say total
`,
        expect: ['3 '],
        absent: ['4 ']
    }
};

for (const [name, {src, expect, absent}] of Object.entries(CORPUS)) {
    test(`forth bench: "${name}" generates Forth that runs correctly on zForth`, async () => {
        const g = generateForth(project(src));
        assert.equal(g.ok, true, `generate refused: ${g.reasons.join('; ')}`);

        // cheap: the generated Forth is still a two-way fixed point.
        const back = forthToPseudocode(g.forth);
        assert.deepEqual(back.warnings, [], `reader degraded:\n${back.pseudocode}`);
        const g2 = generateForth(project(back.pseudocode));
        assert.equal(g2.forth, g.forth, 'round-trip is not a fixed point');

        // the real thing: run the generated Forth on the shipped zForth.
        const r = await runDosToolchain('forth', g.forth, {
            fetchToolchain: async () => ({compiler: FORTH_EXE}),
            maxSteps: 200_000_000
        });
        assert.equal(r.stage, 'compile');
        assert.equal(r.compile.exitCode, 0, 'zForth exited non-zero');
        const screen = r.compile.screen;
        for (const w of expect) {
            assert.ok(screen.includes(w), `expected ${JSON.stringify(w)} in ${JSON.stringify(screen)}`);
        }
        for (const w of (absent || [])) {
            assert.ok(!screen.includes(w), `did NOT expect ${JSON.stringify(w)} in ${JSON.stringify(screen)}`);
        }
    });
}
